"""Generated byte snapshots and private publication; no PDF parsing or OCR."""

import hashlib
import itertools
import json
import os
from pathlib import Path
import stat
import subprocess
import sys

import pytest

import chunking_core
import cleanup_audit
import cleanup_audit_io as io
import ocr_recovery
import storage_policy
from test_cleanup_audit import plan, recovery


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def dump(path, payload):
    path.write_text(json.dumps(payload, ensure_ascii=False) + "\n", encoding="utf-8")


@pytest.fixture
def inputs(tmp_path, monkeypatch):
    paths = {key: tmp_path / (key + suffix) for key, suffix in (
        ("pdf", ".pdf"), ("recovery", ".json"), ("plan", ".json"), ("output", ".json"),
        ("audit_code", ".py"), ("normalizer_code", ".py"))}
    paths["pdf"].write_bytes(b"SYNTHETIC PDF BYTES - NOT PARSED")
    paths["audit_code"].write_bytes(b"# synthetic source generation\n")
    paths["normalizer_code"].write_bytes(b"# synthetic normalizer generation\n")
    monkeypatch.setattr(cleanup_audit, "__file__", str(paths["audit_code"]))
    monkeypatch.setattr(chunking_core, "__file__", str(paths["normalizer_code"]))
    text = "Synthetic\u00a0text.\n42\nRepeated\nRepeated"
    saved = recovery(text)
    saved["source_sha256"] = digest(paths["pdf"])
    dump(paths["recovery"], saved)
    recipe = plan(text)
    recipe.update(source_sha256=digest(paths["pdf"]), recovery_sha256=digest(paths["recovery"]))
    dump(paths["plan"], recipe)
    return paths


def run(paths):
    return io.audit_cleanup_files(*(paths[key] for key in ("pdf", "recovery", "plan", "output")))


def test_private_exact_source_report_plan_and_implementation_bindings(inputs):
    before = {key: path.read_bytes() for key, path in inputs.items() if key != "output"}
    result = run(inputs)
    assert result["summary"]["changed"] == 1
    assert result["inputs"] == {key + "_sha256": digest(inputs[key]) for key in ("pdf", "recovery", "plan")}
    assert result["implementation"]["cleanup_audit_sha256"] == digest(inputs["audit_code"])
    assert result["implementation"]["chunking_core_sha256"] == digest(inputs["normalizer_code"])
    assert json.loads(inputs["output"].read_bytes()) == result
    assert all(path.read_bytes() == before[key] for key, path in inputs.items() if key != "output")
    if os.name == "nt":
        assert storage_policy.windows_path_is_private(inputs["output"], directory=False)
    else:
        assert stat.S_IMODE(inputs["output"].stat().st_mode) == 0o600


@pytest.mark.parametrize("first,second", list(itertools.combinations(("pdf", "recovery", "plan", "output"), 2)))
def test_aliases_rejected_before_input_reads(inputs, monkeypatch, first, second):
    inputs[second] = inputs[first]
    monkeypatch.setattr(io, "_snapshot", lambda *_a, **_k: pytest.fail("read before path checks"))
    with pytest.raises(ValueError):
        run(inputs)


def test_hardlinked_files_and_symlinks_rejected(inputs, tmp_path):
    alias = tmp_path / "alias"
    try:
        os.link(inputs["plan"], alias)
    except OSError:
        pytest.skip("hardlinks unavailable")
    with pytest.raises(ValueError):
        run(inputs)
    link = tmp_path / "symlink"
    try:
        link.symlink_to(inputs["pdf"])
    except OSError:
        return
    with pytest.raises((ValueError, OSError)):
        io._snapshot(link, 1024, json_input=False)


def test_output_exists_is_preserved_without_loading(inputs, monkeypatch):
    inputs["output"].write_bytes(b"OWNER CONTENT")
    monkeypatch.setattr(io, "_snapshot", lambda *_a, **_k: pytest.fail("read before create-only check"))
    with pytest.raises(FileExistsError):
        run(inputs)
    assert inputs["output"].read_bytes() == b"OWNER CONTENT"


def test_noncooperating_output_creator_is_not_overwritten(inputs, monkeypatch):
    original = ocr_recovery._publish_new_report

    def race(temporary, destination):
        destination.write_bytes(b"RACER")
        original(temporary, destination)

    monkeypatch.setattr(ocr_recovery, "_publish_new_report", race)
    with pytest.raises(FileExistsError):
        run(inputs)
    assert inputs["output"].read_bytes() == b"RACER"


@pytest.mark.parametrize("key", ["pdf", "recovery", "plan", "audit_code", "normalizer_code"])
@pytest.mark.parametrize("stage", ["build", "writer"])
def test_all_generations_rechecked_inside_actual_commit(inputs, monkeypatch, key, stage):
    if stage == "build":
        original = cleanup_audit.build_cleanup_audit

        def changed(*args, **kwargs):
            report = original(*args, **kwargs)
            inputs[key].write_bytes(inputs[key].read_bytes() + b" ")
            return report

        monkeypatch.setattr(cleanup_audit, "build_cleanup_audit", changed)
    else:
        original = storage_policy.atomic_write_private_json

        def changed(path, report, **kwargs):
            commit = kwargs["replace_fn"]

            def changed_at_commit(temporary, destination):
                inputs[key].write_bytes(inputs[key].read_bytes() + b" ")
                commit(temporary, destination)

            kwargs["replace_fn"] = changed_at_commit
            return original(path, report, **kwargs)

        monkeypatch.setattr(storage_policy, "atomic_write_private_json", changed)
    with pytest.raises((ValueError, RuntimeError)):
        run(inputs)
    assert not inputs["output"].exists()


@pytest.mark.parametrize("raw", [b'{"a":1,"a":2}', b'{"a":NaN}', b'{"a":1e999}', b'{', b'\xff', b'[]', b'"x"'])
def test_strict_json_is_bounded_and_sanitized(inputs, raw):
    inputs["plan"].write_bytes(raw)
    with pytest.raises(ValueError) as caught:
        run(inputs)
    assert str(inputs["plan"]) not in str(caught.value)
    assert not inputs["output"].exists()


