@pytest.mark.parametrize("late", [False, True])
def test_cancellation_preserves_honest_publication_state(inputs, monkeypatch, late):
    original = ocr_recovery._publish_new_report

    def interrupt(temporary, destination):
        if late:
            original(temporary, destination)
        raise KeyboardInterrupt("SYNTHETIC")

    monkeypatch.setattr(ocr_recovery, "_publish_new_report", interrupt)
    with pytest.raises(KeyboardInterrupt):
        run(inputs)
    assert inputs["output"].exists() is late


def test_postcommit_cleanup_failure_preserves_complete_report(inputs, monkeypatch):
    original = ocr_recovery._publish_new_report

    def fail(temporary, destination):
        original(temporary, destination)
        raise ocr_recovery.ReportCleanupError("SYNTHETIC")

    monkeypatch.setattr(ocr_recovery, "_publish_new_report", fail)
    with pytest.raises(ocr_recovery.ReportCleanupError):
        run(inputs)
    assert json.loads(inputs["output"].read_bytes())["kind"] == "cleanup_fidelity_audit"


@pytest.mark.parametrize("growth_pass", [0, 1])
def test_each_streaming_pass_stops_at_limit_plus_one(tmp_path, monkeypatch, growth_pass):
    path = tmp_path / "synthetic"
    path.write_bytes(b"abcd")
    original = Path.open
    reads = []

    class Handle:
        def __init__(self, handle):
            self.handle, self.attempt, self.position = handle, -1, 0

        def __enter__(self):
            return self

        def __exit__(self, *args):
            self.handle.close()

        def fileno(self):
            return self.handle.fileno()

        def seek(self, offset):
            self.attempt += 1
            self.position = 0
            return self.handle.seek(offset)

        def read(self, count):
            reads.append((self.attempt, count))
            if self.attempt == growth_pass:
                self.position += count
                return b"x" * count
            return self.handle.read(count)

    monkeypatch.setattr(Path, "open", lambda self, *a, **k: Handle(original(self, *a, **k)))
    with pytest.raises(ValueError, match="streaming byte budget"):
        io._snapshot(path, 8, json_input=False)
    assert sum(count for attempt, count in reads if attempt == growth_pass) == 9


def test_digest_change_with_restored_metadata_is_detected(tmp_path, monkeypatch):
    path = tmp_path / "synthetic"
    path.write_bytes(b"abcd")
    original = Path.open

    class Handle:
        def __init__(self, handle):
            self.handle, self.attempt = handle, -1

        def __enter__(self):
            return self

        def __exit__(self, *args):
            self.handle.close()

        def fileno(self):
            return self.handle.fileno()

        def seek(self, offset):
            self.attempt += 1
            return self.handle.seek(offset)

        def read(self, count):
            data = self.handle.read(count)
            return data.replace(b"a", b"z") if self.attempt == 1 else data

    monkeypatch.setattr(Path, "open", lambda self, *a, **k: Handle(original(self, *a, **k)))
    with pytest.raises(RuntimeError, match="changed during hashing"):
        io._snapshot(path, 8, json_input=False)


def test_actual_cli_generated_only_inputs_private_replay_and_create_only(inputs):
    before = {key: digest(inputs[key]) for key in ("pdf", "recovery", "plan")}
    args = sum((["--" + key, str(inputs[key])] for key in ("pdf", "recovery", "plan", "output")), [])
    command = [sys.executable, "tools/audit_cleanup.py", *args]
    completed = subprocess.run(command, capture_output=True, text=True, timeout=30)
    assert completed.returncode == 3, completed.stderr
    assert not completed.stderr
    assert "1 changed" in completed.stdout
    assert all(str(path) not in completed.stdout for path in inputs.values())
    saved = json.loads(inputs["output"].read_bytes())
    assert saved["summary"]["changed"] == 1
    assert saved["inputs"] == {key + "_sha256": value for key, value in before.items()}
    assert "numeric_sequence_changed" in saved["entries"][0]["risks"]
    output_digest = digest(inputs["output"])
    repeated = subprocess.run(command, capture_output=True, text=True, timeout=30)
    assert repeated.returncode == 2
    assert digest(inputs["output"]) == output_digest
    assert {key: digest(inputs[key]) for key in before} == before


@pytest.mark.parametrize("difference", [-1, 0])
def test_exact_serialized_byte_limit_includes_writer_final_lf(inputs, monkeypatch, difference):
    first = dict(inputs, output=inputs["output"].with_name("size-probe.json"))
    run(first)
    size = first["output"].stat().st_size
    monkeypatch.setattr(io, "MAX_OUTPUT_BYTES", size + difference)
    if difference < 0:
        with pytest.raises(ValueError, match="output exceeds byte budget"):
            run(inputs)
        assert not inputs["output"].exists()
    else:
        run(inputs)
        assert inputs["output"].stat().st_size == size


@pytest.mark.parametrize("oversized", [False, True])
def test_staged_mutation_or_oversize_rejected_before_publication(inputs, monkeypatch, oversized):
    original = storage_policy.atomic_write_private_json

    def writer(path, report, **kwargs):
        commit = kwargs["replace_fn"]

        def corrupt(temporary, destination):
            temporary.write_bytes(b"x" * (io.MAX_OUTPUT_BYTES + 1) if oversized else b"{}\n")
            commit(temporary, destination)

        kwargs["replace_fn"] = corrupt
        return original(path, report, **kwargs)

    monkeypatch.setattr(storage_policy, "atomic_write_private_json", writer)
    with pytest.raises((ValueError, RuntimeError)):
        run(inputs)
    assert not inputs["output"].exists()
